# Homebrew formula for Aranet CLI and GUI
# This file is automatically generated by the release workflow.
#
# Install with:
#   brew tap cameronrye/aranet
#   brew install aranet
#
# This installs both the CLI (aranet) and GUI (aranet-gui) binaries.
# For the native macOS app bundle, use: brew install --cask aranet-gui

class Aranet < Formula
  desc "CLI and GUI for Aranet environmental sensors (CO2, radon, temperature, humidity)"
  homepage "https://github.com/cameronrye/aranet"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/cameronrye/aranet/releases/download/v0.2.1/aranet-cli-aarch64-apple-darwin.tar.xz"
      sha256 "98b4148af43b0564b31d2dbd897ae1e2aa367a165e206c9086784d98bf3b808c"

      resource "gui" do
        url "https://github.com/cameronrye/aranet/releases/download/v0.2.1/aranet-gui-aarch64-apple-darwin.tar.xz"
        sha256 "f7d10b5c60cd64676297626a019896e66e9346b93ba24471346ae94c910a5ad9"
      end
    end
    on_intel do
      url "https://github.com/cameronrye/aranet/releases/download/v0.2.1/aranet-cli-x86_64-apple-darwin.tar.xz"
      sha256 "92e6ff4ef5a6eef6f4759dc01042e3dcc82e56227e9a8073b8b3a772bbac8093"

      resource "gui" do
        url "https://github.com/cameronrye/aranet/releases/download/v0.2.1/aranet-gui-x86_64-apple-darwin.tar.xz"
        sha256 "91c6b0559750e1aefe3cf33f04c03420a6c16ac13a7f6097416055d4c5a8d89c"
      end
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/cameronrye/aranet/releases/download/v0.2.1/aranet-cli-x86_64-unknown-linux-gnu.tar.xz"
      sha256 "621870b9262a6f5a6193151de77ae84b348c13cc7c1a4b019b2f73e421e7e6a1"

      resource "gui" do
        url "https://github.com/cameronrye/aranet/releases/download/v0.2.1/aranet-gui-x86_64-unknown-linux-gnu.tar.xz"
        sha256 "c85ada8af66b9a7c469f9a0ebaf31be9ca5562d5c08b179f300acfaef11e6b7f"
      end
    end
  end

  def install
    bin.install "aranet"

    # Install GUI binary from resource
    resource("gui").stage do
      bin.install "aranet-gui"
    end
  end

  def caveats
    <<~EOS
      Aranet requires Bluetooth access.

      On macOS:
        Grant Bluetooth permission when prompted, or add Terminal/iTerm
        to System Preferences > Privacy & Security > Bluetooth.

      Binaries installed:
        aranet      - Command-line interface
        aranet-gui  - Native desktop GUI

      For the macOS .app bundle with Dock icon, install the cask:
        brew install --cask cameronrye/aranet/aranet-gui

      Quick start:
        aranet scan              # Find nearby devices
        aranet read              # Read current values
        aranet-gui               # Launch the GUI
    EOS
  end

  test do
    assert_match "CLI for Aranet environmental sensors", shell_output("#{bin}/aranet --help")
    assert_match version.to_s, shell_output("#{bin}/aranet --version")
  end
end
